import{af as i,ad as s,z as r,J as n,ab as a,x as o}from"./chunks/framework.D-2fLa7v.js";const b=JSON.parse('{"title":"RGB status LEDs","description":"","frontmatter":{"aside":true},"headers":[],"relativePath":"devices/capabilities/rgb-status-leds.md","filePath":"devices/capabilities/rgb-status-leds.md"}'),d={name:"devices/capabilities/rgb-status-leds.md"};function l(c,e,p,h,u,f){const t=s("CapabilityDevices");return r(),n("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1794240761000"},[e[0]||(e[0]=a('<h1 id="rgb-status-leds" tabindex="-1">RGB status LEDs <a class="header-anchor" href="#rgb-status-leds" aria-label="Permalink to &quot;RGB status LEDs&quot;">​</a></h1><p>RGB status LEDs use colour and brightness to indicate device state. They are a different capability from the <a href="/docs/pr/40/devices/capabilities/four-power-leds">four power LED bar display</a> and the older <a href="/docs/pr/40/devices/capabilities/gps-gsm-status-leds">GPS/GSM diagnostic pair</a>.</p><p>A red, green or other colour is meaningful only in the context of the model, firmware, configuration and application controlling it. There is no universal RGB colour table for all Lightbug devices.</p><h2 id="devices" tabindex="-1">Devices <a class="header-anchor" href="#devices" aria-label="Permalink to &quot;Devices&quot;">​</a></h2>',4)),o(t,{capability:"rgb-status-leds"}),e[1]||(e[1]=a('<h2 id="standard-status-and-application-control" tabindex="-1">Standard status and application control <a class="header-anchor" href="#standard-status-and-application-control" aria-label="Permalink to &quot;Standard status and application control&quot;">​</a></h2><p>The same colour can be used for charging, positioning, a configured resting state, an alert or application feedback. Some devices also have separate application-controlled lights. The number and position of those lights are model-specific; the capability name does not define the physical layout.</p><p>Check the device documentation for which display takes precedence and any configurable overrides. A green light does not universally mean full battery, an RTK fix or successful data delivery.</p><h2 id="interpreting-a-pattern" tabindex="-1">Interpreting a pattern <a class="header-anchor" href="#interpreting-a-pattern" aria-label="Permalink to &quot;Interpreting a pattern&quot;">​</a></h2><p>First identify the device and whether it is charging, active, or running an application that controls the lights. Then use the model&#39;s colour table. If the pattern is unfamiliar, use the <a href="/docs/pr/40/guides/leds">LED guide</a> and check the latest successful communication in the app or portal.</p>',5))])}const m=i(d,[["render",l]]);export{b as __pageData,m as default};
